// Controls initial app visibility to avoid header/footer flashing before the Home page renders
function InitialLoaderController() {
  const [ready, setReady] = useState(false);

  useEffect(() => {
    // If the page is already loaded, mark ready quickly
    if (document.readyState === 'complete') {
      setReady(true);
      return;
    }

    const onLoad = () => setReady(true);
    window.addEventListener('load', onLoad);
    // Fallback: ensure ready after 1s even if load doesn't fire
    const t = setTimeout(() => setReady(true), 1000);
    return () => {
      window.removeEventListener('load', onLoad);
      clearTimeout(t);
    };
  }, []);

  if (!ready) {
    // don't show the full-screen loader on first open; allow the Home route to render immediately
    return null;
  }

  return (
    <>
      <Header />
      <SocialIcons />
    </>
  );
}

