function ProblemSlider() {
	const [current, setCurrent] = React.useState(0);
	const visible = 3;
	const total = problems.length;
	const maxIndex = Math.ceil(total / visible);
	const next = () => setCurrent((c) => (c + visible < total ? c + visible : c));
	const prev = () => setCurrent((c) => (c - visible >= 0 ? c - visible : 0));
	const goTo = (idx) => setCurrent(idx * visible);
	return (
		<div className="w-full flex flex-col items-center">
			<div className="flex items-center justify-center gap-4 w-full">
				<button onClick={prev} className="bg-white border border-gray-300 text-blue-700 rounded-full p-3 shadow-lg hover:bg-blue-100 transition">
					&#8592;
				</button>
				<div className="flex gap-8">
					{problems.slice(current, current + visible).map((problem, idx) => {
						let imgSrc;
						try {
							imgSrc = require(`../assets/${problem.title.replace(/ /g, ' ').toLowerCase()}.png`);
						} catch {
							imgSrc = highlight1; // fallback image
						}
						const specialist = problemSpecialistMap[problem.title] || "Specialist";
						return (
							<div key={problem.title + current} className="bg-white rounded-2xl shadow-xl px-8 py-8 min-w-[340px] max-w-md h-[480px] flex flex-col border border-gray-100 transition-transform duration-300 hover:scale-105" style={{ boxShadow: '0 4px 24px 0px rgba(0,0,255,0.08), 0 0 32px 0px rgba(255,0,0,0.10)' }}>
								<img src={imgSrc} alt={problem.title} className="mx-auto mb-4 w-40 h-40 object-contain" />
								<h3 className="text-lg font-bold text-red-600 mb-2 text-center">{problem.title}</h3>
								<ul className="text-gray-700 text-left mb-6 list-disc list-inside">
									{problem.bullets.map((b, i) => <li key={i}>{b}</li>)}
								</ul>
								<Link to={`/book-online`} className="flex justify-center w-full mt-auto">
									<button className="w-5/6 py-2 rounded-full bg-red-500 text-white font-semibold shadow-lg hover:bg-white hover:text-red-600 border-2 border-red-500 hover:scale-105 transition-transform text-base">
										Consult Now - {specialist}
									</button>
								</Link>
							</div>
						);
					})}
				</div>
				<button onClick={next} className="bg-white border border-gray-300 text-blue-700 rounded-full p-3 shadow-lg hover:bg-blue-100 transition">
					&#8594;
				</button>
			</div>
			<div className="flex justify-center mt-8 gap-2">
				{Array.from({ length: maxIndex }).map((_, idx) => (
					<button
						key={idx}
						onClick={() => goTo(idx)}
						className={`w-3 h-3 rounded-full ${current === idx * visible ? 'bg-blue-500' : 'bg-gray-300'} transition`}
						aria-label={`Go to slide ${idx + 1}`}
					/>
				))}
			</div>
		</div>
	);
}



