
import React from "react";
import instagram from "./assets/instagram.svg";
import whatsapp from "./assets/whatsapp.svg";
import youtube from "./assets/youtube.svg";

const socials = [
  {
    name: "Instagram",
    url: "https://www.instagram.com/urjadentalclinicmohali?utm_source=ig_web_button_share_sheet&igsh=ZDNlZDc0MzIxNw==",
    icon: instagram
  },
  {
    name: "WhatsApp",
    url: "https://wa.me/918699969619",
    icon: whatsapp
  },
  {
    name: "YouTube",
    url: "https://www.youtube.com/channel/UClQuZ-x8vpRMU0QsIbjNf9Q",
    icon: youtube
  }
];


const floatStyle = {
  animation: 'floatY 2.5s ease-in-out infinite',
};

const SocialIcons = () => (
  <>
    <style>
      {`
        @keyframes floatY {
          0% { transform: translateY(0); }
          50% { transform: translateY(-16px); }
          100% { transform: translateY(0); }
        }
      `}
    </style>
    <div style={{ position: "fixed", right: 24, top: "40%", zIndex: 1000, display: "flex", flexDirection: "column", gap: 16 }}>
      {socials.map((social, idx) => (
        <a
          key={social.name}
          href={social.url}
          target="_blank"
          rel="noopener noreferrer"
          style={{ background: "#fff", borderRadius: 32, boxShadow: "0 2px 8px #ccc", padding: 8, display: "flex", alignItems: "center", justifyContent: "center", transition: "transform 0.2s", border: "1px solid #eee", ...floatStyle, animationDelay: `${idx * 0.5}s` }}
          title={social.name}
        >
          <img src={social.icon} alt={social.name} style={{ width: 32, height: 32 }} />
        </a>
      ))}
    </div>
  </>
);

export default SocialIcons;
