import React from "react";
import { useLocation, useNavigate } from "react-router-dom";

const FloatingBookButton = () => {
  const location = useLocation();
  const navigate = useNavigate();

  // Hide on Book Now page (assuming route is '/book-online')
  if (location.pathname === "/book-online") return null;

  return (
    <button
      onClick={() => navigate("/book-online")}
      style={{
        position: "fixed",
        bottom: "32px",
        right: "32px",
        zIndex: 1000,
        background: "#f44336",
  borderRadius: "12px",
        boxShadow: "0 4px 24px rgba(244,67,54,0.18)",
        padding: "18px",
        border: "none",
        cursor: "pointer",
        display: "flex",
        alignItems: "center",
        justifyContent: "center"
      }}
      title="Book Appointment"
    >
      <span style={{ display: "flex", alignItems: "center" }}>
        <svg width="32" height="32" viewBox="0 0 15 15" fill="none" xmlns="http://www.w3.org/2000/svg">
          <path fillRule="evenodd" clipRule="evenodd" d="M12 2H13.5C14.3284 2 15 2.67157 15 3.5V13.5C15 14.3284 14.3284 15 13.5 15H1.5C0.671573 15 0 14.3284 0 13.5V3.5C0 2.67157 0.671573 2 1.5 2H3V0H4V2H11V0H12V2ZM6 8H3V7H6V8ZM12 7H9V8H12V7ZM6 11H3V10H6V11ZM9 11H12V10H9V11Z" fill="#fff"/>
        </svg>
        <span style={{ color: "#fff", fontWeight: "bold", marginLeft: "10px", fontSize: "1.1rem" }}>
          Book Appointment
        </span>
      </span>
    </button>
  );
};

export default FloatingBookButton;
