
import React, { useState } from 'react';
import './Header.css';
import { Link } from 'react-router-dom';
import logo from '../logo.svg';

function Header() {
	const [menuOpen, setMenuOpen] = useState(false);
	const [dropdownOpen, setDropdownOpen] = useState(false);
	return (
		<header className="glass-header" style={{ background: '#e53e3e', minHeight: '120px', position: 'relative', overflow: 'visible' }}>
			   <div className="brand flex items-center gap-6 py-2">
				<img src={logo} alt="Urja Dental Clinic Logo" className="brand-logo" style={{ height: '140px', width: '140px', minWidth: '140px' }} />
				   <div className="flex flex-col">
					   <span className="brand-name text-4xl md:text-5xl font-extrabold tracking-wide leading-tight" style={{ color: '#fff', fontWeight: 'bolder', letterSpacing: '0.04em', textShadow: '0 2px 8px rgba(0,0,0,0.18)', fontSize: '2.5rem' }}>Urja Multispeciality Dental Clinic</span>
				   </div>
			   </div>
			<button className="menu-toggle" onClick={() => setMenuOpen(!menuOpen)} aria-label="Toggle menu">
				<span>&#9776;</span>
			</button>
											<nav className={`nav-menu${menuOpen ? ' open' : ''} flex items-center space-x-1`} style={{flexWrap: 'nowrap', overflowX: 'visible', width: '100%', justifyContent: 'flex-end', position: 'relative', zIndex: 99999}}>
												<Link to="/" className="nav-link menu-item" onClick={() => setMenuOpen(false)}>Home</Link>
												<span className="menu-separator"></span>
															<div
																className="nav-link dropdown-trigger menu-item"
																style={{ position: 'relative', cursor: 'pointer' }}
																tabIndex={0}
																onClick={() => setDropdownOpen((open) => !open)}
															>
																<span>Our Services &#9662;</span>
																<div
																	className="dropdown-menu"
																	style={{
																		position: 'absolute',
																		left: 0,
																		top: '100%',
																		background: 'rgba(255,255,255,0.7)',
																		borderRadius: '16px',
																		boxShadow: '0 8px 32px rgba(0,0,0,0.18)',
																		minWidth: '220px',
																		zIndex: 99999,
																		whiteSpace: 'nowrap',
																		padding: '1rem 1.25rem',
																		pointerEvents: dropdownOpen ? 'auto' : 'none',
																		border: '1px solid #eee',
																		marginTop: '8px',
																		display: dropdownOpen ? 'block' : 'none',
																		backdropFilter: 'blur(16px)',
																		WebkitBackdropFilter: 'blur(16px)'
																	}}
																>
																	<ul style={{ margin: 0, padding: 0, listStyle: 'none' }}>
																		<li><Link to="/anti-snoring" className="nav-link menu-item" onClick={() => { setMenuOpen(false); setDropdownOpen(false); }}>Snoring Problem</Link></li>
																		<li><Link to="/braces-treatment" className="nav-link menu-item" onClick={() => { setMenuOpen(false); setDropdownOpen(false); }}>Braces Treatment</Link></li>
																		<li><Link to="/dental-tooth-implant" className="nav-link menu-item" onClick={() => { setMenuOpen(false); setDropdownOpen(false); }}>Dental Tooth Implant</Link></li>
																		<li><Link to="/dentures" className="nav-link menu-item" onClick={() => { setMenuOpen(false); setDropdownOpen(false); }}>Dentures</Link></li>
																		<li><Link to="/diamond-on-tooth" className="nav-link menu-item" onClick={() => { setMenuOpen(false); setDropdownOpen(false); }}>Diamond On Tooth</Link></li>
																		<li><Link to="/full-mouth-dental-crown" className="nav-link menu-item" onClick={() => { setMenuOpen(false); setDropdownOpen(false); }}>Full Mouth Dental Crown</Link></li>
																		<li><Link to="/invisalign" className="nav-link menu-item" onClick={() => { setMenuOpen(false); setDropdownOpen(false); }}>Invisalign</Link></li>
																		<li><Link to="/kids-dentistry" className="nav-link menu-item" onClick={() => { setMenuOpen(false); setDropdownOpen(false); }}>Kids Dentistry</Link></li>
																		<li><Link to="/painless-canal-treatment" className="nav-link menu-item" onClick={() => { setMenuOpen(false); setDropdownOpen(false); }}>Painless Canal Treatment</Link></li>
																		<li><Link to="/proclain-teeth-veeners" className="nav-link menu-item" onClick={() => { setMenuOpen(false); setDropdownOpen(false); }}>Proclain Teeth Veeners</Link></li>
																		<li><Link to="/smile-makeover" className="nav-link menu-item" onClick={() => { setMenuOpen(false); setDropdownOpen(false); }}>Smile Make Over</Link></li>
																		<li><Link to="/teeth-cleaning" className="nav-link menu-item" onClick={() => { setMenuOpen(false); setDropdownOpen(false); }}>Teeth Cleaning</Link></li>
																		<li><Link to="/teeth-whitening-treatment" className="nav-link menu-item" onClick={() => { setMenuOpen(false); setDropdownOpen(false); }}>Teeth Whitening</Link></li>
																		<li><Link to="/tooth-filling" className="nav-link menu-item" onClick={() => { setMenuOpen(false); setDropdownOpen(false); }}>Tooth Filling</Link></li>
																		<li><Link to="/tooth-removal" className="nav-link menu-item" onClick={() => { setMenuOpen(false); setDropdownOpen(false); }}>Tooth Removal</Link></li>
																	</ul>
																</div>
															</div>
												<span className="menu-separator"></span>
												<Link to="/our-team" className="nav-link menu-item" onClick={() => setMenuOpen(false)}>Our Team</Link>
												<span className="menu-separator"></span>
												<Link to="/holistic-dentist" className="nav-link menu-item" onClick={() => setMenuOpen(false)}>Holistic Dentist</Link>
												<span className="menu-separator"></span>
												<Link to="/happy-patients" className="nav-link menu-item" onClick={() => setMenuOpen(false)}>Happy Patients</Link>
												<span className="menu-separator"></span>
												<Link to="/clinic-tour" className="nav-link menu-item" onClick={() => setMenuOpen(false)}>Clinic Tour</Link>
												<span className="menu-separator"></span>
												<Link to="/dental-tourism" className="nav-link menu-item" onClick={() => setMenuOpen(false)}>Dental Tourism</Link>
												<span className="menu-separator"></span>
												<Link to="/cases-pictures" className="nav-link menu-item" onClick={() => setMenuOpen(false)}>Cases Pictures</Link>
												
											</nav>
									   <style>{`
													 .dropdown-trigger {
														 position: relative;
														 cursor: pointer;
													 }
										   .dropdown-menu {
											   z-index: 100000 !important;
											   box-shadow: 0 8px 32px rgba(0,0,0,0.18);
											   position: absolute;
											   left: 0;
											   top: 100%;
											   min-width: 220px;
											   background: rgba(255,255,255,0.7);
											   border-radius: 16px;
											   border: 1px solid #eee;
											   margin-top: 8px;
											   padding: 1rem 1.25rem;
											   backdrop-filter: blur(16px);
											   -webkit-backdrop-filter: blur(16px);
										   }
													 /* Dropdown now opens on click, not hover */
										   .dropdown-menu ul {
											   margin: 0;
											   padding: 0;
											   list-style: none;
										   }
										   .dropdown-menu li {
											   padding: 0.25rem 0;
										   }
										   .nav-link.menu-item {
											   color: #fff !important;
											   font-weight: bold !important;
											   background: none !important;
											   border: none !important;
											   transition: text-shadow 0.2s;
											   display: inline-block;
											   padding: 0.15rem 0.3rem;
											   position: relative;
											   white-space: nowrap;
										   }
										   .dropdown-menu .nav-link.menu-item {
											   color: #333 !important;
											   font-weight: 500 !important;
											   background: none !important;
											   border: none !important;
											   padding: 0.25rem 0.5rem;
											   text-shadow: none;
											   display: block;
										   }
										   .dropdown-menu .nav-link.menu-item:hover {
											   color: #e53e3e !important;
											   background: #f7f7f7 !important;
											   border-radius: 4px;
										   }
										   .nav-link.menu-item:hover {
											   text-shadow: 0 0 8px #fff, 0 0 16px #fff;
										   }
										   .menu-separator {
											   display: inline-block;
											   width: 2px;
											   height: 16px;
											   background: rgba(255,255,255,0.6);
											   margin: 0 0.15rem;
											   vertical-align: middle;
										   }
									   `}</style>
		</header>
	);
}

export default Header;
